year = int(input("연도: "))
if (year % 4 == 0 and year % 100 != 0) or (year % 400 == 0):
    print(year, "년은 윤년입니다.")
else:
    print(year, "년은 윤년이 아닙니다.")

registered = {"Mina", "Jun", "Sora", "Jin"}
attended = {"Jun", "Sora", "Ara"}
print(sorted(registered & attended))
print(sorted(registered - attended))
print(sorted(attended - registered))

english_dict = {"one": "하나", "two": "둘", "three": "셋"}
queries = ["one", "four", "two"]
for word in queries:
    meaning = english_dict.get(word, "등록되지 않은 단어")
    print(word, meaning)
